export function buildExpandedGrammar(rows: Record<Level, LegacyRow[]>): Record<Level, Grammar[]> {
  const levels: Level[] = ['N5', 'N4', 'N3', 'N2', 'N1'];
  return Object.fromEntries(levels.map(level => {
    if (rows[level].length !== lessons[level].length) throw new Error(`Missing grammar supplements for ${level}`);
    return [level, rows[level].map((row, index): Grammar => {
      const [title, original, ja, en, prompt, correct, wrong1, wrong2, reason] = row;
      const [formation, guidance, fourthChoice, first, second, practice1, practice2] = lessons[level][index];
      const interpretation = (example: Example): Exercise => [
        `Choose the best English meaning: ${example[0]}`, example[2], example[3], example[4], example[5],
        `“${example[0]}” means “${example[2]}” in this example. ${guidance.split('. ')[0]}.`,
      ];
      const originalPrompt = level === 'N5' && index === 7
        ? 'Complete the existence sentence for a dog: 犬が＿。'
        : prompt;
      const exercises: Exercise[] = [
        [originalPrompt, correct, wrong1, wrong2, fourthChoice, `The correct answer is “${correct}”. ${reason}`],
        practice1, practice2, interpretation(first), interpretation(second),
      ];
      return {
        id: `grammar-${level}-${String(index + 1).padStart(2, '0')}`,
        title, level,
        explanation: `${original}\n\nFormation: ${formation}\n\nUsage and cautions: ${guidance}`,
        examples: [{ ja, en }, ...[first, second].map(([ja, reading, en]) => ({ ja, reading, en }))],
        questions: exercises.map(([prompt, correct, wrong1, wrong2, wrong3, explanation], questionIndex) => {
          const choices = [correct, wrong1, wrong2, wrong3];
          const offset = (index + questionIndex) % choices.length;
          return { prompt, choices: [...choices.slice(offset), ...choices.slice(0, offset)], answer: (4 - offset) % 4, explanation };
        }),
        source: 'Original curriculum; CC BY-SA 4.0. Level placement is an estimate, not an official JLPT syllabus.',
      };
    })];
  })) as Record<Level, Grammar[]>;
}
